SELECT SEQ, TYPE, TITLE, TOP_FIXED , CREATE_DATETIME, CREATE_IDX , UPDATE_DATETIME, UPDATE_IDX FROM TB_BOARD WHERE 1 = 1 AND DELETED = 0 AND TYPE = #{type}
AND TITLE LIKE CONCAT('%', #{searchValue}, '%')
AND CONTENT LIKE CONCAT('%', #{searchValue}, '%')
AND (TITLE LIKE CONCAT('%', #{searchValue}, '%') OR CONTENT LIKE CONCAT('%', #{searchValue}, '%'))
ORDER BY TOP_FIXED DESC, SEQ DESC LIMIT #{startDataNumber}, #{dataCount}

